import json, pathlib
from string import Template
source = json.loads(pathlib.Path('/app/benchmark/source_data.json').read_text())
html = Template(r'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<title>Renewable Energy Cost Revolution, 2010–2024</title>
<style>
  :root{
    --paper:#fbf8f1;
    --ink:#1b2733;
    --muted:#67727e;
    --grid:#d9d0c1;
    --solar:#d99018;
    --wind:#0b8f83;
    --battery:#7a4b8f;
    --fossil:#6b6258;
    --sub-cons:#9b684a;
    --sub-prod:#c9a06c;
  }
  html,body{margin:0;background:var(--paper);}
  #wrap{width:1600px;height:1100px;background:var(--paper);font-family: Georgia, 'Times New Roman', serif;color:var(--ink);}
  svg{display:block;width:1600px;height:1100px;background:var(--paper);}
  .sans{font-family: Arial, Helvetica, sans-serif;}
  .mono{font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;}
  .title{font-size:39px;font-weight:700;letter-spacing:-0.7px;fill:var(--ink);}
  .subtitle{font-size:18px;fill:#4b5661;}
  .section{font-size:19px;font-weight:700;fill:var(--ink);letter-spacing:.2px;}
  .axis text{font-family:Arial,Helvetica,sans-serif;font-size:13px;fill:#59636d;}
  .axis path,.axis line{stroke:#8d867c;shape-rendering:crispEdges;}
  .grid line{stroke:var(--grid);stroke-width:1;stroke-dasharray:2 5;}
  .grid path{display:none;}
  .label{font-family:Arial,Helvetica,sans-serif;font-size:14px;fill:#3d4752;}
  .small{font-family:Arial,Helvetica,sans-serif;font-size:12px;fill:#66717d;}
  .legend{font-family:Arial,Helvetica,sans-serif;font-size:14px;fill:#2a333d;}
  .callout{font-family:Arial,Helvetica,sans-serif;font-size:13px;fill:#2c3540;}
  .callout-strong{font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:700;fill:#17222d;}
  .chip{fill:#fffdf8;stroke:#cfc5b6;stroke-width:1.1;}
  .panel-border{fill:none;stroke:#d2c8b8;stroke-width:1;}
</style>
</head>
<body>
<div id="wrap"><svg id="chart" viewBox="0 0 1600 1100" role="img" aria-label="Renewable energy cost decline, capacity growth, and fossil fuel subsidies from 2010 to 2024"></svg></div>
<script>
const data = $DATA;
const svg = document.getElementById('chart');
const NS = 'http://www.w3.org/2000/svg';
const W = 1600, H = 1100;
const colors = {solar:'#d99018', wind:'#0b8f83', battery:'#7a4b8f', fossil:'#6b6258', cons:'#9b684a', prod:'#c9a06c'};
function el(name, attrs={}, parent=svg){ const e=document.createElementNS(NS,name); for(const [k,v] of Object.entries(attrs)){ if(k==='text') e.textContent=v; else e.setAttribute(k,v); } parent.appendChild(e); return e; }
function group(attrs={}){ return el('g', attrs); }
function linePath(points){ return points.map((p,i)=>(i?'L':'M')+p[0].toFixed(2)+','+p[1].toFixed(2)).join(' '); }
function areaPath(topPts, bottomPts){ return linePath(topPts)+' L '+bottomPts.slice().reverse().map(p=>p[0].toFixed(2)+','+p[1].toFixed(2)).join(' L ')+' Z'; }
function scaleLinear(d0,d1,r0,r1){ return v => r0 + (v-d0)*(r1-r0)/(d1-d0); }
function scaleLog(d0,d1,r0,r1){ const a=Math.log(d0), b=Math.log(d1); return v => r0 + (Math.log(v)-a)*(r1-r0)/(b-a); }
function interpSeries(rows, key){
  const out = {};
  for(let y=2010;y<=2024;y++){
    const exact = rows.find(r=>r.year===y);
    if(exact){ out[y]=exact[key]; continue; }
    let lo=null, hi=null;
    for(const r of rows){ if(r.year<y) lo=r; if(r.year>y){ hi=r; break; } }
    out[y]=lo[key]+(hi[key]-lo[key])*(y-lo.year)/(hi.year-lo.year);
  }
  return out;
}

// Title block
el('text',{x:70,y:62,class:'title',text:'Clean energy got cheaper as it scaled — while fossil subsidies persisted'});
el('text',{x:70,y:95,class:'subtitle sans',text:'2010–2024: renewable LCOE collapse, accelerating installed capacity, and annual fossil fuel subsidy scale'});

// Data preparation
const lcoe = data.lcoe_trends.data;
const cap = data.installed_capacity.data;
const subs = data.fossil_fuel_subsidies.data;
const fossilRaw = data.fossil_fuel_lcoe_range.data.map(r=>({year:r.year, low:Math.min(r.gas_ccgt_low,r.coal_low), high:Math.max(r.gas_ccgt_high,r.coal_high)}));
const fossilLow = interpSeries(fossilRaw, 'low');
function decline(first,last){ return Math.round((1-last/first)*100); }
const dSolar = decline(lcoe[0].solar_pv, lcoe[lcoe.length-1].solar_pv);
const dWind = decline(lcoe[0].onshore_wind, lcoe[lcoe.length-1].onshore_wind);
const dBatt = decline(lcoe[0].battery_storage, lcoe[lcoe.length-1].battery_storage);
const crossSolar = lcoe.find(r=>r.solar_pv <= fossilLow[r.year]).year;
const crossWind = lcoe.find(r=>r.onshore_wind <= fossilLow[r.year]).year;

// KPI chips
const chips = [
  {x:70, w:270, title:`Solar PV −${dSolar}%`, sub:'LCOE: $359 → $33/MWh', color:colors.solar},
  {x:360, w:270, title:`Battery storage −${dBatt}%`, sub:'LCOE: $1,100 → $102/MWh', color:colors.battery},
  {x:650, w:270, title:`Solar capacity 49×`, sub:'40 → 1,950 GW cumulative', color:colors.solar},
  {x:940, w:270, title:`Fossil subsidies`, sub:'2024: $550bn; 2022 peak: $700bn', color:colors.fossil},
  {x:1230, w:300, title:'Cost crossovers', sub:`Wind ${crossWind}; solar ${crossSolar} below fossil band`, color:'#243447'}
];
for(const c of chips){
  el('rect',{x:c.x,y:122,width:c.w,height:70,rx:12,class:'chip'});
  el('circle',{cx:c.x+22,cy:151,r:6,fill:c.color});
  el('text',{x:c.x+38,y:148,class:'callout-strong sans',text:c.title});
  el('text',{x:c.x+38,y:173,class:'small sans',text:c.sub});
}

// Panels
const p1={x:80,y:235,w:930,h:455};
const p2={x:1085,y:235,w:430,h:455};
const p3={x:80,y:775,w:1435,h:230};
[p1,p2,p3].forEach(p=>el('rect',{x:p.x-20,y:p.y-18,width:p.w+40,height:p.h+38,rx:10,class:'panel-border'}));

// Panel 1 LCOE
el('text',{x:p1.x,y:p1.y-34,class:'section sans',text:'1  Costs collapsed; wind and solar moved below new fossil generation'});
const x1=scaleLinear(2010,2024,p1.x,p1.x+p1.w);
const y1=scaleLog(30,1200,p1.y+p1.h,p1.y);
const yticks=[30,50,75,100,200,500,1000];
for(const t of yticks){
  const y=y1(t); el('line',{x1:p1.x,x2:p1.x+p1.w,y1:y,y2:y,stroke:'#d9d0c1','stroke-dasharray':'2 5'});
  el('text',{x:p1.x-12,y:y+4,'text-anchor':'end',class:'small sans',text:`$${t}`});
}
for(const y of [2010,2012,2014,2016,2018,2020,2022,2024]){
  const xx=x1(y); el('line',{x1:xx,x2:xx,y1:p1.y,y2:p1.y+p1.h,stroke:'#e5ddcf','stroke-dasharray':'1 7'});
  el('text',{x:xx,y:p1.y+p1.h+28,'text-anchor':'middle',class:'small sans',text:y});
}
el('line',{x1:p1.x,y1:p1.y+p1.h,x2:p1.x+p1.w,y2:p1.y+p1.h,stroke:'#8d867c'});
el('line',{x1:p1.x,y1:p1.y,x2:p1.x,y2:p1.y+p1.h,stroke:'#8d867c'});
el('text',{x:p1.x+p1.w/2,y:p1.y+p1.h+58,'text-anchor':'middle',class:'label sans',text:'Year'});
el('text',{x:p1.x-58,y:p1.y+p1.h/2,transform:`rotate(-90 ${p1.x-58} ${p1.y+p1.h/2})`,'text-anchor':'middle',class:'label sans',text:'LCOE, 2023 USD per MWh (log scale)'});

const fossilTop=fossilRaw.map(r=>[x1(r.year),y1(r.high)]);
const fossilBot=fossilRaw.map(r=>[x1(r.year),y1(r.low)]);
el('path',{d:areaPath(fossilTop,fossilBot),fill:'#6b6258',opacity:.16});
el('path',{d:linePath(fossilTop),fill:'none',stroke:'#6b6258','stroke-width':1.3,'stroke-dasharray':'5 4',opacity:.75});
el('path',{d:linePath(fossilBot),fill:'none',stroke:'#6b6258','stroke-width':1.3,'stroke-dasharray':'5 4',opacity:.75});
el('text',{x:x1(2011.1),y:y1(67),class:'small sans',fill:'#675f55',text:'new fossil generation cost band'});

function drawSeries(key, color, name, width=3.8){
  const pts=lcoe.map(r=>[x1(r.year),y1(r[key])]);
  el('path',{d:linePath(pts),fill:'none',stroke:color,'stroke-width':width,'stroke-linecap':'round','stroke-linejoin':'round'});
  for(const r of lcoe.filter((_,i)=>i%2===0 || r.year===2024)) el('circle',{cx:x1(r.year),cy:y1(r[key]),r:3.5,fill:'#fbf8f1',stroke:color,'stroke-width':2});
  const last=lcoe[lcoe.length-1];
  el('text',{x:x1(2024)+10,y:y1(last[key])+4,class:'legend sans',fill:color,text:`${name} $${last[key]}`});
}
drawSeries('solar_pv',colors.solar,'Solar PV');
drawSeries('onshore_wind',colors.wind,'Onshore wind');
drawSeries('battery_storage',colors.battery,'Battery storage',3.3);

function crossover(year, key, color, label, dy){
  const row=lcoe.find(r=>r.year===year), xx=x1(year), yy=y1(row[key]);
  el('line',{x1:xx,x2:xx,y1:p1.y,y2:p1.y+p1.h,stroke:color,'stroke-width':1.2,'stroke-dasharray':'4 5',opacity:.72});
  el('circle',{cx:xx,cy:yy,r:7,fill:color,stroke:'#fffdf8','stroke-width':2});
  el('path',{d:`M${xx+7},${yy-8} C${xx+45},${yy-46} ${xx+65},${yy+dy-38} ${xx+92},${yy+dy-26}`,fill:'none',stroke:color,'stroke-width':1.5});
  el('rect',{x:xx+92,y:yy+dy-48,width:178,height:47,rx:8,fill:'#fffdf8',stroke:color,'stroke-width':1.1,opacity:.98});
  el('text',{x:xx+106,y:yy+dy-28,class:'callout-strong sans',fill:color,text:label});
  el('text',{x:xx+106,y:yy+dy-10,class:'small sans',text:'below broad fossil low bound'});
}
crossover(crossWind,'onshore_wind',colors.wind,`Wind crossover: ${crossWind}`,-8);
crossover(crossSolar,'solar_pv',colors.solar,`Solar crossover: ${crossSolar}`,44);

// Battery annotation
const b2010=lcoe[0], b2024=lcoe[lcoe.length-1];
el('line',{x1:x1(2010),y1:y1(b2010.battery_storage),x2:x1(2024),y2:y1(b2024.battery_storage),stroke:colors.battery,'stroke-width':1.2,'stroke-dasharray':'2 6',opacity:.45});
el('rect',{x:x1(2011.2),y:y1(440),width:245,height:60,rx:9,fill:'#fffdf8',stroke:colors.battery,'stroke-width':1.1});
el('text',{x:x1(2011.45),y:y1(400),class:'callout-strong sans',fill:colors.battery,text:'Battery cost collapse'});
el('text',{x:x1(2011.45),y:y1(350),class:'small sans',text:'$1,100/MWh → $102/MWh'});

// Legend panel 1
const legX=p1.x+p1.w-250, legY=p1.y+20;
[
  ['Solar PV LCOE',colors.solar],['Onshore wind LCOE',colors.wind],['Battery storage LCOE',colors.battery],['Fossil LCOE range','#6b6258']
].forEach((d,i)=>{const y=legY+i*24; if(i<3) el('line',{x1:legX,y1:y,x2:legX+30,y2:y,stroke:d[1],'stroke-width':4,'stroke-linecap':'round'}); else el('rect',{x:legX,y:y-6,width:30,height:12,fill:d[1],opacity:.18,stroke:d[1]}); el('text',{x:legX+42,y:y+5,class:'legend sans',text:d[0]});});

// Panel 2 capacity
el('text',{x:p2.x,y:p2.y-34,class:'section sans',text:'2  Installed capacity accelerated after 2018'});
